import app from 'flarum/admin/app';
import { call } from '../common/api';
export const overview = () => call('GET', '/admin/overview');
export const products = () => call('GET', '/admin/products');
export const saveProduct = (data, id) => call(id ? 'PATCH' : 'POST', id ? `/admin/products/${id}` : '/admin/products', data);
export const deleteProduct = id => call('DELETE', `/admin/products/${id}`);
export const orderProducts = ids => call('POST', '/admin/products/order', {
  ids
});
export const unlockTypes = () => call('GET', '/admin/unlocks');
export const searchUnlocks = (type, q) => call('GET', '/admin/unlocks', undefined, {
  type,
  q
});
export const purchases = params => call('GET', '/admin/purchases', undefined, params);
export const purchaseAction = (id, action) => call('POST', `/admin/purchases/${id}/${action}`);
export const grant = data => call('POST', '/admin/grants', data);
export const webhooks = (failed = false) => call('GET', '/admin/webhooks', undefined, failed ? {
  failed: '1'
} : undefined);
export const replay = id => call('POST', `/admin/webhooks/${id}/replay`);
export const connectPayPal = data => call('POST', '/admin/paypal', data);
export const connectStripe = data => call('POST', '/admin/stripe', data);
export const coupons = () => call('GET', '/admin/coupons');
export const createCoupon = body => call('POST', '/admin/coupons', body);
export const deleteCoupon = id => call('DELETE', `/admin/coupons/${id}`);
export const connectBtcpay = url => call('POST', '/admin/btcpay', {
  url
});
export const connectNowpayments = body => call('POST', '/admin/nowpayments', body);
export const disconnectCrypto = key => call('POST', `/admin/${key}/disconnect`);

/** Where an ad can go, in the order the admin sees them. Mirrors Model\Ad::LOCATIONS. */
export const LOCATIONS = ['header', 'below_header', 'sidebar', 'between_discussions', 'after_first_post', 'between_posts', 'discussion_sidebar', 'above_footer', 'footer'];
export const ads = () => call('GET', '/admin/ads');
export const saveAd = (body, id) => call(id ? 'PATCH' : 'POST', id ? `/admin/ads/${id}` : '/admin/ads', body);
export const deleteAd = id => call('DELETE', `/admin/ads/${id}`);
export const uploadAdImage = (id, file) => {
  const body = new FormData();
  body.append('image', file);
  return app.request({
    method: 'POST',
    url: app.forum.attribute('apiUrl') + `/kiosk/admin/ads/${id}/image`,
    body,
    serialize: raw => raw
  });
};